const desafioParaBriefing = {
  "Perda ou desorganização de leads": "Operação Comercial e Leads",
  "Falta de suporte técnico": "Técnico WordPress/WooCommerce",
  "Processo manual e repetitivo": "Automação, Integrações e Desenvolvimento",
  "Integração entre sistemas": "Automação, Integrações e Desenvolvimento",
  "Problemas em WordPress ou WooCommerce": "Técnico WordPress/WooCommerce",
  "Desenvolvimento de nova funcionalidade": "Automação, Integrações e Desenvolvimento",
  "Performance ou segurança": "Técnico WordPress/WooCommerce",
  "Outro": "Triagem Geral/Outro"
};

/**
 * Retorna o briefing recomendado para um determinado desafio.
 * @param {string} desafio - O texto do desafio selecionado no formulário.
 * @returns {string} O briefing correspondente ou undefined se não encontrado.
 */
function mapearBriefing(desafio) {
  return desafioParaBriefing[desafio];
}
const briefing = mapearBriefing($json['body']['your-service'].trim());

const endereco = $('Webhook').first().json.headers['user-agent'].split('; ')[1];
const ambiente = endereco.startsWith('https://sandbox.') ? 'sandbox' : 'produção';

return [{
  name: $json['body']['your-name'].trim() || '',
  email: $json['body']['your-email'].trim() || '',
  company: $json['body']['your-company'].trim() || '',
  service: $json['body']['your-service'].trim() || '',
  problem: $json['body']['your-problem'].trim() || '',
  role: $json['body']['your-role'].trim() || '',
  tel: $json['body']['your-tel'].trim() || '',
  schedule: $json['body']['your-schedule'].trim() || '',
  briefing: briefing,
  environment: ambiente,
}];
